insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,care_notice,status) values
('atyopsis-moluccensis','Bambu Karides','Atyopsis moluccensis','karidesler','fish','Orta','Barışçıl','Ön bacaklarındaki yelpazelerle akıntıdan ince besin süzen, iri ve barışçıl bir tatlı su karidesidir.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.5–7.8"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl"], ["Beslenme", "Süzerek mikro yem ve organik partikül"], ["Üreme", "Larvaları acı/denizel evre gerektirir"], ["Köken", "Güneydoğu Asya"], ["Ömür", "3–5 yıl"], ["Özellikler", "Filtre karidesi, akıntı"]]'::jsonb,array['bambu karides','atyopsis moluccensis','bamboo shrimp','wood shrimp']::text[],false,null,'published'),
('atya-gabonensis','Vampir Karides','Atya gabonensis','karidesler','fish','Orta','Barışçıl','Mavi-gri tonlara çıkabilen iri bir filtre karidesidir; güçlü akıntı ve saklanma alanı ister.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.5–7.8"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl"], ["Beslenme", "Süzücü"], ["Üreme", "Larval gelişim karmaşıktır"], ["Köken", "Batı Afrika"], ["Ömür", "4–6 yıl"], ["Özellikler", "Filtre karidesi, iri"]]'::jsonb,array['vampir karides','atya gabonensis','vampire shrimp','african fan shrimp']::text[],true,null,'published'),
('caridina-dennerli','Sulawesi Kardinal Karides','Caridina dennerli','karidesler','fish','Zor','Barışçıl','Beyaz benekli koyu kırmızı rengiyle Sulawesi''nin en ikonik karideslerindendir; stabil alkali su ister.','[["Yetişkin boy", "2,5 cm"], ["Sıcaklık", "27–30 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl"], ["Beslenme", "Biofilm, mikro yem"], ["Üreme", "Doğrudan gelişim; minyatür yavru"], ["Köken", "Sulawesi, Matano sistemi"], ["Ömür", "1.5–2.5 yıl"], ["Özellikler", "Sulawesi, kırmızı, biofilm"]]'::jsonb,array['sulawesi kardinal karides','caridina dennerli','cardinal shrimp','sulawesi shrimp']::text[],true,null,'published'),
('caridina-woltereckae','Sulawesi Harlequin Karides','Caridina woltereckae','karidesler','fish','Zor','Barışçıl','Kontrast desenli, çok hassas bir Sulawesi endemiğidir.','[["Yetişkin boy", "2,5 cm"], ["Sıcaklık", "27–30 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl"], ["Beslenme", "Biofilm"], ["Üreme", "Doğrudan gelişim"], ["Köken", "Sulawesi"], ["Ömür", "1.5–2.5 yıl"], ["Özellikler", "Sulawesi, nadir, desenli"]]'::jsonb,array['sulawesi harlequin karides','caridina woltereckae','harlequin sulawesi shrimp']::text[],true,null,'published'),
('caridina-glaubrechti','Sulawesi White Orchid Karides','Caridina glaubrechti','karidesler','fish','Zor','Barışçıl','Açık gövde ve zarif desenleriyle sıcak, alkali ve çok stabil su isteyen Sulawesi karidesidir.','[["Yetişkin boy", "2,5 cm"], ["Sıcaklık", "27–30 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl"], ["Beslenme", "Biofilm"], ["Üreme", "Doğrudan gelişim"], ["Köken", "Sulawesi"], ["Ömür", "1.5–2.5 yıl"], ["Özellikler", "Sulawesi, beyaz, nadir"]]'::jsonb,array['sulawesi white orchid karides','caridina glaubrechti','white orchid shrimp']::text[],true,null,'published'),
('caridina-babaulti','Babaulti Karides','Caridina babaulti','karidesler','fish','Orta','Barışçıl','Yeşil, kahverengi veya çizgili formları görülebilen dayanıklı sayılabilecek küçük Caridina''dır.','[["Yetişkin boy", "3,5 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.5–7.8"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor, biofilm"], ["Üreme", "Doğrudan gelişim"], ["Köken", "Hindistan"], ["Ömür", "1.5–2 yıl"], ["Özellikler", "Caridina, küçük, renkli"]]'::jsonb,array['babaulti karides','caridina babaulti','green babaulti shrimp']::text[],true,null,'published'),
('caridina-pareparensis-parvidentata','Malaya Karides','Caridina pareparensis parvidentata','karidesler','fish','Orta','Barışçıl','Renk değiştirebilen, alg ve biofilm tüketen küçük Güneydoğu Asya karidesidir.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.8"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor, biofilm"], ["Üreme", "Larval evre bulunur"], ["Köken", "Güneydoğu Asya"], ["Ömür", "1.5–2 yıl"], ["Özellikler", "Alg, biofilm, Caridina"]]'::jsonb,array['malaya karides','caridina pareparensis parvidentata','malaya shrimp','caridina parvidentata','pareparensis']::text[],true,null,'published'),
('caridina-gracilirostris','Pinokyo Karides','Caridina gracilirostris','karidesler','fish','Orta','Barışçıl','Uzun kırmızı rostrumu ve şeffaf gövdesiyle kolay tanınır; üremede acı su larval evresi vardır.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl"], ["Beslenme", "Alg, biofilm, omnivor"], ["Üreme", "Larvaları acı su ister"], ["Köken", "Hint-Pasifik"], ["Ömür", "2–3 yıl"], ["Özellikler", "Uzun burun, alg, acı su larva"]]'::jsonb,array['pinokyo karides','caridina gracilirostris','pinocchio shrimp','red nose shrimp']::text[],false,null,'published'),
('caridina-serratirostris','Ninja Karides','Caridina serratirostris','karidesler','fish','Orta','Barışçıl','Rengini çevreye göre değiştirebilmesiyle bilinen küçük bir alg/biofilm karidesidir.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.8"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl"], ["Beslenme", "Biofilm, omnivor"], ["Üreme", "Larval evre nedeniyle üretim zor"], ["Köken", "Hint-Pasifik"], ["Ömür", "1.5–2 yıl"], ["Özellikler", "Renk değiştiren, nano"]]'::jsonb,array['ninja karides','caridina serratirostris','ninja shrimp']::text[],true,null,'published'),
('caridina-cantonensis-taiwan-bee','Tayvan Bee Karides','Caridina cantonensis ''Taiwan Bee''','karidesler','fish','Zor','Barışçıl','Crystal ve Taiwan Bee hatlarının temel türlerinden; yumuşak, serin ve stabil suyu sever.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "20–24 °C"], ["pH", "5.5–6.8"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl"], ["Beslenme", "Biofilm, özel karides yemleri"], ["Üreme", "Doğrudan gelişim"], ["Köken", "Güney Çin"], ["Ömür", "1.5–2 yıl"], ["Özellikler", "Bee shrimp, yumuşak su"]]'::jsonb,array['tayvan bee karides','taiwan bee','taiwan bee shrimp']::text[],false,null,'published'),
('caridina-serrata','Tangerine Tiger Karides','Caridina serrata','karidesler','fish','Orta','Barışçıl','Turuncu gövdesiyle hobiye giren küçük bir Caridina; bee karideslere göre bir miktar toleranslıdır.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "20–25 °C"], ["pH", "6.0–7.2"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl"], ["Beslenme", "Biofilm, omnivor"], ["Üreme", "Doğrudan gelişim"], ["Köken", "Güney Çin"], ["Ömür", "1.5–2 yıl"], ["Özellikler", "Tiger, turuncu, Caridina"]]'::jsonb,array['tangerine tiger karides','caridina serrata','tangerine tiger shrimp']::text[],true,null,'published'),
('caridina-mariae','Tiger Karides','Caridina mariae','karidesler','fish','Orta','Barışçıl','Koyu enine bantlarıyla bilinen tiger karides hatlarının tür temelidir.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "20–25 °C"], ["pH", "6.0–7.2"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl"], ["Beslenme", "Biofilm, omnivor"], ["Üreme", "Doğrudan gelişim"], ["Köken", "Güney Çin"], ["Ömür", "1.5–2 yıl"], ["Özellikler", "Tiger shrimp, çizgili"]]'::jsonb,array['tiger karides','caridina mariae','tiger shrimp']::text[],true,null,'published'),
('macrobrachium-assamense','Kırmızı Pençe Makro Karides','Macrobrachium assamense','karidesler','fish','Orta','Yarı agresif','Uzun kolları ve belirgin pençeleriyle cüce karideslerden daha yırtıcı karakter gösterebilir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "80 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, küçük omurgasız"], ["Üreme", "Doğrudan/az larvalı gelişim"], ["Köken", "Güney Asya"], ["Ömür", "2–4 yıl"], ["Özellikler", "Macrobrachium, pençeli"]]'::jsonb,array['kırmızı pençe makro karides','macrobrachium assamense','red claw shrimp']::text[],true,null,'published'),
('palaemonetes-paludosus','Cam Karides','Palaemonetes paludosus','karidesler','fish','Kolay','Barışçıl-fırsatçı','Şeffaf gövdesiyle klasik ghost shrimp görünümündedir; dayanıklı ve fırsatçı beslenir.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "18–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl-fırsatçı"], ["Beslenme", "Omnivor"], ["Üreme", "Larval gelişim"], ["Köken", "Kuzey Amerika"], ["Ömür", "1–2 yıl"], ["Özellikler", "Şeffaf, ghost shrimp"]]'::jsonb,array['cam karides','palaemonetes paludosus','ghost shrimp']::text[],false,null,'published'),
